mapper.select:
SELECT COUNT(*)
FROM tb_review
WHERE store_id = #{storeId}

SELECT COUNT(*)
FROM tb_review
WHERE user_id = #{userId}

mapper.update:
UPDATE tb_review
SET rating            = #{rating},
    content           = #{content},
    images            = #{images},
    modified_datetime = #{modifiedDatetime}
WHERE idx = #{idx}

mapper.select:
SELECT COALESCE(AVG(CAST(rating AS DECIMAL(3, 2))), 0.0)
FROM tb_review
WHERE store_id = #{storeId}

SELECT CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END
FROM tb_review
WHERE user_id = #{userId}
  AND order_order_id = #{orderOrderId}
